log=string.sub(log,#log-50000)
end
writefile("SakuraUI_errors.log",log)
end
end)
pcall(function()
if lib and lib.Notify then
lib:Notify({Title="SakuraUI Error",Description=tostring(label)..": "..msg,Duration=5,Type="error"})
end
end)
end
return ok,res
end








