local P,Q,S=ax.R-O.R,ax.G-O.G,ax.B-O.B
return P*P+Q*Q+S*S<0.003
end

local function ax(O)
if aw(O,ar)or aw(O,au)or aw(O,av)then
return ao
elseif aw(O,as)then
return ap
elseif aw(O,at)then
return aq
end
return nil
end




