end
elseif S:IsA("TextLabel")or S:IsA("TextButton")then
local T=ax(S.TextColor3)
if T then S.TextColor3=T end
elseif S:IsA("UIStroke")then
local T=ax(S.Color)
if T then S.Color=T end
end
O(S)
end
end

if self.screenGui then
O(self.screenGui)
end
if D then
O(D)
end


