function y:_GetUIFontChoices()
if self._fontChoices then
return self._fontChoices
end
local out={}
local ok1,famGothamR=pcall(Font.new,"rbxasset://fonts/families/GothamSSm.json",Enum.FontWeight.SemiBold)
local ok2,famGothamB=pcall(Font.new,"rbxasset://fonts/families/GothamSSm.json",Enum.FontWeight.Bold)
if ok1 and ok2 then
table.insert(out,{Name="Gotham (Default)",Regular=famGothamR,Bold=famGothamB})
end
local ok3,famBuildR=pcall(Font.new,"rbxasset://fonts/families/BuilderSans.json",Enum.FontWeight.SemiBold)
local ok4,famBuildB=pcall(Font.new,"rbxasset://fonts/families/BuilderSans.json",Enum.FontWeight.Bold)
if ok3 and ok4 then
table.insert(out,{Name="BuilderSans",Regular=famBuildR,Bold=famBuildB})
end
local items={}
pcall(function()
items=Enum.Font:GetEnumItems()
end)
table.sort(items,function(f1,f2)
return f1.Name<f2.Name
end)
for _,item in ipairs(items)do
if item.Name~="Gotham"and item.Name~="BuilderSans"then
local base=Font.fromEnum(item)
local boldFont=base
local hasBold,boldEnum=pcall(function()
return Enum.Font[item.Name.."Bold"]
end)
if hasBold and boldEnum then
boldFont=Font.fromEnum(boldEnum)
else
local hasHeavy,heavyEnum=pcall(function()
return Enum.Font[item.Name.."Heavy"]
end)
if hasHeavy and heavyEnum then
boldFont=Font.fromEnum(heavyEnum)
end
end
table.insert(out,{Name=item.Name,Regular=base,Bold=boldFont})
end
end
self._fontChoices=out
return out
end

function y:_ApplyUIFont(name)
local choices=self:_GetUIFontChoices()
local chosen=nil
for _,choice in ipairs(choices)do
if choice.Name==name then
chosen=choice
break
end
end
if not chosen then
chosen=choices[1]
end
if not chosen then
return
end
self._uiFontName=chosen.Name
v.Regular=chosen.Regular
v.Bold=chosen.Bold
if self.screenGui then
local boldWeights={}
for _,weightName in ipairs({"Bold","ExtraBold","Heavy","Black"})do
local ok,weight=pcall(function()
return Enum.FontWeight[weightName]
end)
if ok and weight then
boldWeights[weight]=true
end
end
for _,obj in ipairs(self.screenGui:GetDescendants())do
if obj:IsA("TextLabel")or obj:IsA("TextButton")or obj:IsA("TextBox")then
local isBold=false
local ok,weight=pcall(function()
return obj.FontFace.Weight
end)
if ok and weight and boldWeights[weight]then
isBold=true
end
pcall(function()
obj.FontFace=isBold and chosen.Bold or chosen.Regular
end)
end
end
end
pcall(function()
self:_SaveUISettings()
end)
end

