function y:_StartEmojiRain()
if true then return end
if self._emojiAlive then
return
end
if self._emojisEnabled==false then
return
end
self._emojiAlive=true
self._emojiThreads={}
local area=self:_EnsureAmbientBackground()
local holder=F("Frame",{
Name="EmojiHolder",
BackgroundTransparency=1,
Size=UDim2.new(1,0,1,0),
ZIndex=0,
Parent=area
})
self._emojiHolder=holder
local sets=self:_GetEmojiSets()
local pool=sets[self._emojiSet or"Faces"]or sets.Faces
for _=1,8 do
local thread=task.spawn(function()
local emSize=math.random(20,30)
local label=F("TextLabel",{
Name="Emoji",
Text=pool[math.random(1,#pool)],
FontFace=v.Regular,
TextColor3=Color3.new(1,1,1),
TextTransparency=1,
TextSize=emSize-4,
BackgroundTransparency=1,
BorderSizePixel=0,
Size=UDim2.fromOffset(emSize,emSize),
TextXAlignment=Enum.TextXAlignment.Center,
TextYAlignment=Enum.TextYAlignment.Center,
Rotation=math.random(-20,20),
ZIndex=0,
Parent=holder
})
local firstDrop=true
while self._emojiAlive and label.Parent do
local sz=holder.AbsoluteSize
if sz.X<20 or sz.Y<20 then
task.wait(0.1)
else
local dropW=label.AbsoluteSize.X
local dropH=label.AbsoluteSize.Y
local travel=math.max(1,sz.Y-dropH)
local speed=0.45+math.random()*0.75
local dur=math.max(4,travel/(speed*60))
local startX=math.random(0,math.max(1,sz.X-dropW))
local sway=6+math.random()*14
local freq=0.35+math.random()*0.6
local drift=(math.random()-0.5)*30
local phase=math.random()*6.28
local born=os.clock()-(firstDrop and math.random()*dur*0.9 or 0)
firstDrop=false
local baseTrans=0.05+math.random()*0.25
while self._emojiAlive and label.Parent do
local q=(os.clock()-born)/dur
if q>=1 then
break
end
local curSize=holder.AbsoluteSize
if curSize.X>=20 and curSize.Y>=20 then
local posX=math.clamp(startX+math.sin(q*math.pi*2*freq+phase)*sway+drift*q,0,math.max(1,curSize.X-dropW))
local posY=math.clamp((curSize.Y-dropH)*q,0,math.max(1,curSize.Y-dropH))
local areaPos=holder.AbsolutePosition
local guiSize=self.screenGui.AbsoluteSize
local screenX=areaPos.X+posX
local screenY=areaPos.Y+posY
if screenX<0 then
posX=posX-screenX
end
if screenX+dropW>guiSize.X then
posX=posX-(screenX+dropW-guiSize.X)
end
if screenY<0 then
posY=posY-screenY
end
if screenY+dropH>guiSize.Y then
posY=posY-(screenY+dropH-guiSize.Y)
end
label.Position=UDim2.fromOffset(posX,posY)
end
if q<0.1 then
label.TextTransparency=math.clamp(baseTrans+0.7-(q/0.1)*0.7,0,1)
elseif q>0.6 then
label.TextTransparency=math.clamp(baseTrans+((q-0.6)/0.4)*(1-baseTrans),0,1)
else
label.TextTransparency=baseTrans
end
label.Rotation=math.sin(q*math.pi*2*freq+phase)*12
task.wait(0.016)
end
end
end
pcall(function()
label:Destroy()
end)
end)
table.insert(self._emojiThreads,thread)
end
end

function y:_StopEmojiRain()
if self._emojiThreads then
for _,thread in ipairs(self._emojiThreads)do
pcall(task.cancel,thread)
end
self._emojiThreads={}
end
self._emojiAlive=false
if self._emojiHolder then
pcall(function()
self._emojiHolder:Destroy()
end)
self._emojiHolder=nil
end
end

function y:_SetEmojisEnabled(state)
self._emojisEnabled=state
if state then
self:_StartEmojiRain()
else
self:_StopEmojiRain()
end
self:_SaveUISettings()
end

function y:_SetEmojiSet(name)
self._emojiSet=name
if self._emojiAlive then
self:_StopEmojiRain()
self:_StartEmojiRain()
end
self:_SaveUISettings()
end

