function y:Resize(size)
if not self.container then return false end
local w=size and size.X.Offset or u.Window.Width
local h=size and size.Y.Offset or u.Window.Height
w=math.clamp(w,u.MinWindow.Width,u.MaxWindow.Width)
h=math.clamp(h,u.MinWindow.Height,u.MaxWindow.Height)
local cam=workspace.CurrentCamera
if cam then
local vp=cam.ViewportSize
w=math.min(w,math.max(u.MinWindow.Width,vp.X-20))
h=math.min(h,math.max(u.MinWindow.Height,vp.Y-80))
end
local pos=self.container.Position
local dw=w-self.container.Size.X.Offset
local dh=h-self.container.Size.Y.Offset
E(self.container,{
Size=UDim2.new(0,w,0,h),
Position=UDim2.new(pos.X.Scale,pos.X.Offset-dw/2,pos.Y.Scale,pos.Y.Offset-dh/2)
},x.Normal)
return true
end

