function y:SaveConfig(ak)
if not writefile then
self:Notify({
Title="Error",
Description="Config system not supported",
Duration=3
})
return false
end

ac()

local al={}
for am,an in pairs(self._configElements)do
local ao=an.getValue()

if typeof(ao)=="Color3"then
ao={R=ao.R,G=ao.G,B=ao.B,_type="Color3"}
elseif typeof(ao)=="EnumItem"then
ao={_type="EnumItem",_enum=tostring(ao.EnumType),_value=ao.Name}
end

al[am]=ao
end

local am,an=pcall(function()
writefile("SakuraConfigs/"..ak..".json",h:JSONEncode(al))
end)

if am then
self._currentConfig=ak
self:Notify({
Title="Config Saved",
Description="Saved as: "..ak,
Duration=2,
Icon="rbxassetid://10723356507"
})
return true
else
self:Notify({
Title="Error",
Description="Failed to save config",
Duration=3
})
return false
end
end

function y:LoadConfig(ak)
if not readfile or not isfile then
self:Notify({
Title="Error",
Description="Config system not supported",
Duration=3
})
return false
end

local al="SakuraConfigs/"..ak..".json"
if not isfile(al)then
self:Notify({
Title="Error",
Description="Config not found: "..ak,
Duration=3
})
return false
end

local am,an=pcall(function()
return h:JSONDecode(readfile(al))
end)

if not am or not an then
self:Notify({
Title="Error",
Description="Failed to load config",
Duration=3
})
return false
end

for ao,ap in pairs(an)do
if self._configElements[ao]then
if type(ap)=="table"and ap._type=="Color3"then
ap=Color3.new(ap.R,ap.G,ap.B)
elseif type(ap)=="table"and ap._type=="EnumItem"then
ap=Enum[ap._enum][ap._value]
end

pcall(function()
self._configElements[ao].setValue(ap)
end)
end
end

self._currentConfig=ak
self:Notify({
Title="Config Loaded",
Description="Loaded: "..ak,
Duration=2,
Icon="rbxassetid://10723356507"
})
return true
end

function y:DeleteConfig(ak)
if not delfile or not isfile then
return false
end

local al="SakuraConfigs/"..ak..".json"
if isfile(al)then
delfile(al)
self:Notify({
Title="Config Deleted",
Description="Deleted: "..ak,
Duration=2
})
return true
end
return false
end

