function y:SetAutoSave(ak)
self._autoSave=ak
if ak then
if self._autoSaveThread then
task.cancel(self._autoSaveThread)
self._autoSaveThread=nil
end
self._autoSaveThread=task.spawn(function()
while self._autoSave and self.screenGui and self.screenGui.Parent do
task.wait(30)
if self._autoSave then
self:SaveConfig(self._currentConfig)
end
end
end)
elseif self._autoSaveThread then
task.cancel(self._autoSaveThread)
self._autoSaveThread=nil
end
end

